import type { ApiClientModal } from '@scalar/api-client/modal';

// The operation pages, generated by starlight-openapi, get a button that opens the request client over the page.
// The page names the operation it documents, so nothing here depends on another program's URL scheme.
const base = import.meta.env.BASE_URL.replace(/\/$/, '');
const host = document.getElementById('api-client');
const button = document.querySelector<HTMLButtonElement>('button[data-test-request]');

// The spec carries the public registries. A local instance is always offered, and any other address is added from the
// client's own server list.
const LOCAL_SERVER = { url: 'http://localhost:8080', description: 'Local instance' };
const STORAGE_KEY = 'registry.server';

type Server = { url: string; description?: string };

const readRemembered = () => {
	try {
		return localStorage.getItem(STORAGE_KEY) ?? '';
	} catch {
		return '';
	}
};

if (host && button) {
	// Scalar's utilities are scoped under `.scalar-app`, and its colours live in `.light-mode` / `.dark-mode`.
	const themeClass = () => (document.documentElement.dataset.theme === 'dark' ? 'dark-mode' : 'light-mode');
	// Out of Starlight's `.main-pane`: `isolation: isolate` there would trap the fixed overlay.
	document.body.append(host);

	const route = () => ({
		path: button.dataset.path ?? '',
		method: (button.dataset.method ?? 'get').toLowerCase(),
	});

	const remembered = readRemembered();
	let servers: Server[] = remembered ? [LOCAL_SERVER, { url: remembered, description: 'Custom' }] : [LOCAL_SERVER];
	let client: ApiClientModal | undefined;
	let observer: MutationObserver | undefined;

	// The client reads its server list when the workspace is built, so a new address means building it again.
	const build = async () => {
		// The client is large and only the operation pages can open it, so it is fetched on the first click.
		const [{ createApiClientModal }, { createWorkspaceStore }] = await Promise.all([
			import('@scalar/api-client/modal'),
			import('@scalar/workspace-store/client'),
		]);
		await import('@scalar/api-client/style.css');

		const response = await fetch(`${base}/openapi.json`);
		if (!response.ok) throw new Error(`openapi.json: ${response.status}`);
		const spec = await response.json();
		const merged: Server[] = [...((spec.servers ?? []) as Server[])];
		for (const server of servers) {
			if (!merged.some((entry) => entry.url === server.url)) merged.push(server);
		}
		spec.servers = merged;

		const workspaceStore = createWorkspaceStore();
		await workspaceStore.addDocument({ name: 'registry', document: spec });
		host.className = `scalar-app ${themeClass()}`;
		client = createApiClientModal({ el: host, workspaceStore, options: { proxyUrl: 'https://proxy.scalar.com' } });
		watchServerList();
	};

	// Scalar's server list is its own component, drawn from the workspace: it has no row for an address the reader
	// types. That row is added here, and the address it returns rebuilds the client with the new entry.
	const addCustomRow = () => {
		// The observer fires on every change inside the client, so the cheap check comes first.
		if (host.querySelector('[data-custom-server]')) return;
		// Several scroll lists are mounted in the client; the server list is the one whose rows name an address.
		const list = [...host.querySelectorAll<HTMLElement>('.custom-scroll')].find((element) =>
			[...element.querySelectorAll('button span')].some((span) => /^https?:\/\//.test(span.textContent?.trim() ?? '')),
		);
		if (!list || list.querySelector('[data-custom-server]')) return;

		const row = document.createElement('div');
		row.className = 'group/item flex min-h-fit flex-col rounded border border-transparent';
		const control = document.createElement('button');
		control.type = 'button';
		control.dataset.customServer = '';
		control.className = 'flex min-h-8 cursor-pointer items-center gap-1.5 rounded px-1.5 hover:bg-b-2';
		const dot = document.createElement('div');
		dot.className = 'flex size-4 items-center justify-center p-0.75 shadow-border text-transparent rounded-full';
		const label = document.createElement('span');
		label.className = 'overflow-hidden text-ellipsis whitespace-nowrap';
		label.textContent = 'Custom address…';
		control.append(dot, label);
		row.append(control);
		list.append(row);

		control.addEventListener('click', (event) => {
			event.preventDefault();
			event.stopPropagation();
			const answer = window.prompt('Registry base URL', readRemembered() || LOCAL_SERVER.url);
			if (!answer) return;
			const url = answer.trim().replace(/\/$/, '');
			try {
				if (!/^https?:$/.test(new URL(url).protocol)) return;
			} catch {
				return;
			}
			servers = [...servers.filter((server) => server.url !== url), { url, description: 'Custom' }];
			try {
				localStorage.setItem(STORAGE_KEY, url);
			} catch {
				/* private mode */
			}
			restart();
		});
	};

	const watchServerList = () => {
		addCustomRow();
		observer?.disconnect();
		observer = new MutationObserver(() => addCustomRow());
		observer.observe(host, { childList: true, subtree: true });
	};

	// One build at a time: a second click while the client loads must not mount a second one.
	let ready: Promise<void> | undefined;
	const ensure = () => (ready ??= build());

	const fail = () => {
		button.disabled = true;
		button.textContent = 'Request client unavailable';
	};

	const restart = async () => {
		const current = route();
		try {
			observer?.disconnect();
			client?.app.unmount();
			host.replaceChildren();
			client = undefined;
			ready = undefined;
			await ensure();
			client?.open(current);
		} catch {
			fail();
		}
	};

	const open = async () => {
		try {
			await ensure();
			client?.open(route());
		} catch {
			ready = undefined;
			fail();
		}
	};

	button.addEventListener('click', () => {
		void open();
	});
}
